  "test": "import os
import pytest
from langfuse import observe
from langfuse._client.attributes import LangfuseOtelSpanAttributes
from langfuse._client.observe import _ContextPreservedSyncGeneratorWrapper
from langfuse._client.observe import _ContextPreservedAsyncGeneratorWrapper


def _finished_spans_by_name(memory_exporter, name):
    return [s for s in memory_exporter.get_finished_spans() if s.name == name]


def test_output_capture_respects_env(monkeypatch, langfuse_memory_client, memory_exporter):
    # Disable output capture via env var
    monkeypatch.setenv(
        "LANGFUSE_OBSERVE_DECORATOR_OUTPUT_CAPTURE_ENABLED", "false"
    )

    @observe(name="env_test_span", as_type="span")
    def my_func():
        return {"key": "value"}

    result = my_func()
    assert result == {"key": "value"}

    # Flush spans to exporter
    langfuse_memory_client.flush()

    spans = _finished_spans_by_name(memory_exporter, "env_test_span")
    assert len(spans) == 1
    span = spans[0]
    # The output attribute should NOT be recorded because the env var disables it
    assert LangfuseOtelSpanAttributes.OBSERVATION_OUTPUT not in span.attributes
